-- Fictitious seed only; transaction-local. No reset or hosted execution.
begin;
select no_plan();
grant execute on function private.fixture_id(text,integer) to authenticated;
insert into auth.sessions(id,user_id) values
 (private.fixture_id('course-session',1),private.fixture_id('admin',1)),
 (private.fixture_id('course-session',2),private.fixture_id('candidate',1)),
 (private.fixture_id('course-session',3),private.fixture_id('company',1));
select set_config('course.candidate',private.fixture_id('profile',1)::text,true);
select set_config('course.other_candidate',private.fixture_id('profile',2)::text,true);
select set_config('course.participations',(select count(*)::text from public.participations),true);
select set_config('course.job_referrals',(select count(*)::text from public.referrals),true);
select ok(not has_function_privilege('anon','public.save_municipal_course(text,text,boolean,uuid)','execute'),'Anonymous cannot maintain courses');
select ok(not has_function_privilege('anon','public.create_course_referral(uuid,uuid)','execute'),'Anonymous cannot refer');
select ok(not has_table_privilege('anon','public.course_referrals','select'),'Anonymous cannot read referrals');
select ok(not has_column_privilege('anon','public.municipal_courses','created_by','select'),'Public metadata excludes staff attribution');
select ok(not has_table_privilege('authenticated','public.course_referrals','insert,update,delete'),'Direct referral writes forbidden');
select set_config('request.jwt.claim.sub',private.fixture_id('admin',1)::text,true);
select set_config('request.jwt.claims',jsonb_build_object('sub',private.fixture_id('admin',1),'session_id',private.fixture_id('course-session',1))::text,true);
set local role authenticated;
select set_config('course.id',public.save_municipal_course('Curso ficticio','https://funes.gob.ar/curso',true)::text,true);
select set_config('course.draft',public.save_municipal_course('Curso sin publicar','https://funes.gob.ar/otro',false)::text,true);
select set_config('course.referral',public.create_course_referral(current_setting('course.candidate')::uuid,current_setting('course.id')::uuid)::text,true);
select lives_ok(format('select public.create_course_referral(%L,%L)',current_setting('course.other_candidate'),current_setting('course.id')),'Independent referrals for multiple candidates');
select throws_ok($$select public.save_municipal_course('Curso','javascript:alert(1)',true)$$,'P0001','INVALID_INPUT','Unsafe scheme rejected');
select throws_ok($$select public.save_municipal_course('Curso','https://user:pass@funes.gob.ar/curso',true)$$,'P0001','INVALID_INPUT','Credential URL rejected');
select throws_ok($$select public.save_municipal_course('Curso','https://funes.gob.ar/ curso',true)$$,'P0001','INVALID_INPUT','Whitespace URL rejected');
select throws_ok($$select public.save_municipal_course('Curso','https://funes.gob.ar/%0a',true)$$,'P0001','INVALID_INPUT','Encoded control rejected');
select throws_ok(format('select public.create_course_referral(%L,%L)',current_setting('course.candidate'),current_setting('course.draft')),'P0001','INVALID_TRANSITION','Unpublished course cannot receive referrals');
select throws_ok(format('select public.create_course_referral(%L,%L)',current_setting('course.candidate'),'00000000-0000-4000-8000-000000000000'),'P0001','NOT_FOUND','Unknown course rejected');
select lives_ok(format('select public.save_municipal_course(%L,%L,false,%L)','Curso actualizado','https://funes.gob.ar/nuevo',current_setting('course.id')),'Administrator can update and unpublish metadata');
reset role;
select is((select course_title from public.course_referrals where id=current_setting('course.referral')::uuid),'Curso ficticio','History preserves original course title after edit');
select is((select course_url from public.course_referrals where id=current_setting('course.referral')::uuid),'https://funes.gob.ar/curso','History preserves original course URL');
select ok(exists(select 1 from public.course_referrals where id=current_setting('course.referral')::uuid and referred_at is not null and referred_by=(select id from public.accounts where auth_user_id=private.fixture_id('admin',1))),'Persisted actor and time');
select ok(exists(select 1 from public.audit_events where entity_type='course_referrals' and entity_id=current_setting('course.referral')::uuid and action='referral_created' and actor_account_id=(select id from public.accounts where auth_user_id=private.fixture_id('admin',1))),'Referral audit is attributed');
select ok(exists(select 1 from public.audit_events where entity_type='municipal_courses' and entity_id=current_setting('course.id')::uuid and action='course_link_created'),'Course creation audited');
select ok(exists(select 1 from public.audit_events where entity_type='municipal_courses' and entity_id=current_setting('course.id')::uuid and action='course_link_updated'),'Course maintenance audited');
select is((select count(*)::text from public.participations),current_setting('course.participations'),'No job application created or modified by course flow');
select is((select count(*)::text from public.referrals),current_setting('course.job_referrals'),'No company referral created');
select throws_ok($$update public.course_referrals set course_title='Changed'$$,'P0001','APPEND_ONLY','History immutable even for privileged SQL');
select throws_ok($$delete from public.course_referrals$$,'P0001','APPEND_ONLY','No destructive deletion of history');
update public.candidate_profiles set status='archived',archived_at=clock_timestamp(),archived_by=(select id from public.accounts where auth_user_id=private.fixture_id('admin',1)) where id=current_setting('course.candidate')::uuid;
set local role authenticated;
select throws_ok(format('select public.create_course_referral(%L,%L)',current_setting('course.candidate'),current_setting('course.draft')),'P0001','INVALID_TRANSITION','Archived candidate rejected');
select is((select count(*) from public.course_referrals where candidate_id=current_setting('course.candidate')::uuid),1::bigint,'Archived candidate retains readable history for staff');
reset role;
select set_config('request.jwt.claim.sub',private.fixture_id('candidate',1)::text,true);
select set_config('request.jwt.claims',jsonb_build_object('sub',private.fixture_id('candidate',1),'session_id',private.fixture_id('course-session',2))::text,true);
set local role authenticated;
select is((select count(*) from public.course_referrals),0::bigint,'Candidate cannot read own or another candidate course referrals');
select throws_ok(format('select public.create_course_referral(%L,%L)',current_setting('course.other_candidate'),current_setting('course.draft')),'P0001','FORBIDDEN','Candidate cannot refer another candidate');
select throws_ok($$select public.save_municipal_course('Curso','https://funes.gob.ar/curso',true)$$,'P0001','FORBIDDEN','Candidate cannot create course');
reset role;
select set_config('request.jwt.claim.sub',private.fixture_id('company',1)::text,true);
select set_config('request.jwt.claims',jsonb_build_object('sub',private.fixture_id('company',1),'session_id',private.fixture_id('course-session',3))::text,true);
set local role authenticated;
select is((select count(*) from public.course_referrals),0::bigint,'Company cannot read any course referrals');
select throws_ok(format('select public.create_course_referral(%L,%L)',current_setting('course.other_candidate'),current_setting('course.draft')),'P0001','FORBIDDEN','Company cannot create course referral');
reset role;
select set_config('request.jwt.claim.sub',private.fixture_id('admin',1)::text,true);
select set_config('request.jwt.claims',jsonb_build_object('sub',private.fixture_id('admin',1),'session_id',private.fixture_id('course-session',1))::text,true);
delete from auth.sessions where id=private.fixture_id('course-session',1);
set local role authenticated;
select is((select count(*) from public.course_referrals),0::bigint,'Revoked administrator session cannot read history');
select throws_ok($$select public.save_municipal_course('Curso','https://funes.gob.ar/curso',true)$$,'P0001','AUTH_REQUIRED','Revoked session cannot maintain courses');
reset role;
-- Restore one published item without touching immutable historical snapshots.
update public.municipal_courses set published=true where id=current_setting('course.id')::uuid;
set local role anon;
select is((select count(*) from public.municipal_courses),1::bigint,'Anonymous sees published metadata only');
select lives_ok($$select title,url from public.municipal_courses$$,'Public can read course links');
reset role;
select * from finish();
rollback;
